const UINT32 rbd_audio_frames = 26000;
const UINT32 rbd_audio_wire = 26000;

#define RBD_AUDIO_RATE  16000
#define RBD_PAD_MARGIN_MS  500

static int rbd_marker_present(void) {
    EFI_FILE_PROTOCOL *root = efi_boot_volume_root();
    if (!root) return 0;
    int found = efi_file_exists_root(root, RBD_MARKER);
    root->Close(root);
    return found;
}

static void rbd_marker_clear(void) {
    EFI_FILE_PROTOCOL *root = efi_boot_volume_root();
    if (!root) return;
    EFI_FILE_PROTOCOL *f = NULL;
    EFI_STATUS st = root->Open(root, &f, RBD_MARKER,
                               EFI_FILE_MODE_READ | EFI_FILE_MODE_WRITE, 0);
    if (!EFI_ERROR(st) && f) f->Delete(f);
    root->Close(root);
}

static void rbd_marker_write(void) {
    static const CHAR8 tag[] = RBD_MARKER_TAG;
    EFI_STATUS st = cap_save_file(RBD_MARKER, (const UINT8*)tag,
                                  sizeof(tag) - 1);
    if (EFI_ERROR(st))
        efi_log(L"rbd: could not write the marker - the loop holds this time");
}

void rbd_arm_on_reboot(int enabled) {
    if (!enabled) return;
    if (efi_rand() % RBD_ODDS != 0) return;
    efi_log(L"rbd: the die came up wrong - arming Return by Death");
    rbd_marker_write();
}

static INT16 *rbd_pcm8_build(UINTN *frames_out) {
    *frames_out = 0;
    UINTN in_frames = rbd_audio_frames;
    if (!in_frames) return NULL;
    UINTN out_frames =
        (UINTN)(((UINT64)in_frames * HDA_SAMPLE_RATE) / RBD_AUDIO_RATE);
    if (!out_frames) return NULL;

    INT16 *src = efi_allocate_pool(in_frames * 2 * sizeof(INT16));
    if (!src) return NULL;
    const UINT8 *wl = rbd_audio_data;
    const UINT8 *wr = rbd_audio_data + rbd_audio_wire;
    for (UINTN i = 0; i < in_frames; i++) {
        src[i * 2]     = (INT16)(((INT32)wl[i] - 128) << 8);
        src[i * 2 + 1] = (INT16)(((INT32)wr[i] - 128) << 8);
    }

    INT16 *out = efi_allocate_pool(out_frames * 2 * sizeof(INT16));
    if (!out) {
        efi_free_pool(src);
        return NULL;
    }
    pcm_resample_stereo(src, in_frames, RBD_AUDIO_RATE, out, out_frames,
                        HDA_SAMPLE_RATE);
    efi_free_pool(src);

    *frames_out = out_frames;
    return out;
}

int rbd_check_and_play(gui_state_t *gui) {
    if (!rbd_marker_present()) return 0;

    efi_log(L"rbd: marker found - Return by Death");
    rbd_marker_clear();

    INT16 *pcm = NULL;
    UINTN frames = 0;
    pcm = rbd_pcm8_build(&frames);
    if (!pcm) efi_log(L"rbd: embedded sting decode failed - silent");

    UINTN active = (pcm && frames) ? frames : 0;

    UINTN pad_ms = (UINTN)rbd_scene_duration_ms() + (UINTN)RBD_PAD_MARGIN_MS;
    pcm = pcm_pad_silence(pcm, &frames,
                          frames + pad_ms * (UINTN)HDA_SAMPLE_RATE / 1000);

    void *audio = NULL;
    if (pcm && frames) {
        int st = HDA_HW_ERROR;
        audio = hda_play_begin(pcm, frames, active, &st);
        if (!audio) {
            CHAR16 msg[128];
            SPrint(msg, sizeof(msg), L"rbd: no sound - %s", hda_status_str(st));
            efi_log(msg);
        }
    }

    gui_rbd_screen(gui);
    hda_play_end(audio);
    if (pcm) efi_free_pool(pcm);
    return 1;
}
